TH = 30  # watts
edges = [(t, agg[t] - agg[t - 1]) for t in range(1, 60)
         if abs(agg[t] - agg[t - 1]) > TH]
labels = kmeans_1d([abs(dp) for _, dp in edges], k=3)
name = {0: "lamp", 1: "fridge", 2: "kettle"}
on_since = {"lamp": None, "fridge": None, "kettle": None}
pairs = []
for (t, dp), k in zip(edges, labels):
    app = name[k]
    if dp > 0:
        if on_since[app] is None:
            on_since[app] = t
        # else: already on, this ON edge is dropped
    else:
        if on_since[app] is not None:
            pairs.append((app, on_since[app], t))
            on_since[app] = None
        # else: OFF with no open ON, dropped
for app, t0 in on_since.items():
    if t0 is not None:
        pairs.append((app, t0, 60))  # still on at the end
